package kome.common.data;

import java.util.*;
import net.minecraft.nbt.NBTTagCompound;
import org.junit.Test;
import static org.junit.Assert.*;
import static kome.common.data.KOMEKnightCommission.*;

public class KOMEKnightCommissionStateTest {
    static KOMEProgressionNpcRef liege(){return new KOMEProgressionNpcRef(UUID.randomUUID().toString(),"Aldor","rohan",0,0,64,0);}
    static KOMEKnightCommission commission(Type type){KOMEKnightCommission a=new KOMEKnightCommission(type,liege());a.x=640;a.y=65;a.z=640;a.destinationX=1000;a.destinationZ=1000;a.place="Roadside refuge";return a;}
    @Test public void knightWithLiegeCanAccept(){KOMEKnightServiceRecord s=new KOMEKnightServiceRecord();KOMEKnightCommission a=commission(Type.RELIEF);assertTrue(s.offer(a));assertTrue(s.accept(KOMEProgressionRank.KNIGHT,a.liege,"ROHAN"));assertEquals(Stage.ACCEPTED,a.stage);}
    @Test public void everyOtherRankIsRejected(){for(KOMEProgressionRank rank:KOMEProgressionRank.values())if(rank!=KOMEProgressionRank.KNIGHT){KOMEKnightServiceRecord s=new KOMEKnightServiceRecord();KOMEKnightCommission a=commission(Type.RELIEF);s.offer(a);assertFalse(rank.name(),s.accept(rank,a.liege,"rohan"));}}
    @Test public void wrongFactionAndWrongLiegeCannotAccept(){KOMEKnightServiceRecord s=new KOMEKnightServiceRecord();KOMEKnightCommission a=commission(Type.RELIEF);s.offer(a);assertFalse(s.accept(KOMEProgressionRank.KNIGHT,a.liege,"gondor"));assertFalse(s.accept(KOMEProgressionRank.KNIGHT,liege(),"rohan"));assertFalse(s.accept(KOMEProgressionRank.KNIGHT,KOMEProgressionNpcRef.EMPTY,"rohan"));}
    @Test public void onlyOneOrdinaryChargeAndOnlyOneAcceptance(){KOMEKnightServiceRecord s=new KOMEKnightServiceRecord();KOMEKnightCommission a=commission(Type.RELIEF);assertTrue(s.offer(a));assertFalse(s.offer(commission(Type.STOLEN_GOODS)));assertTrue(s.accept(KOMEProgressionRank.KNIGHT,a.liege,"rohan"));assertFalse(s.accept(KOMEProgressionRank.KNIGHT,a.liege,"rohan"));assertSame(a,s.assignment());}
    @Test public void assignmentPersistsEveryConcreteTypeAndStructuredFields(){for(Type type:Type.values()){KOMEPlayerProgression p=new KOMEPlayerProgression();p.setCanonicalRank(KOMEProgressionRank.KNIGHT);KOMEKnightCommission a=commission(type);a.stage=Stage.ACTIVE;a.participated=true;a.encounterCreated=true;a.enemyFaction="mordor";a.revision=2;a.retries=1;a.nextRecoveryTick=500;a.goods.add(new Goods("minecraft:bread",0,32));a.goods.get(0).delivered=7;a.enemyClasses.add("lotr.common.entity.npc.LOTREntityMordorOrc");a.actors.add(new Actor(UUID.randomUUID().toString(),a.enemyClasses.get(0),Role.ENEMY,640,65,640));p.getKnightService().offer(a);KOMEPlayerProgression loaded=new KOMEPlayerProgression();loaded.readFromNBT(p.writeToNBT());assertEquals(a.writeToNBT(),loaded.getKnightService().assignment().writeToNBT());}}
    @Test public void oldSavesHaveNoChargeOrService(){KOMEPlayerProgression p=new KOMEPlayerProgression();p.readFromNBT(new NBTTagCompound());assertNull(p.getKnightService().assignment());assertTrue(p.getKnightService().completedTypes().isEmpty());}
    @Test public void fieldSuccessRequiresReportAndCorrectLiege(){KOMEKnightServiceRecord s=new KOMEKnightServiceRecord();KOMEKnightCommission a=commission(Type.BORDER_INCURSION);s.offer(a);a.stage=Stage.ACTIVE;assertFalse(s.report(a.liege));assertTrue(s.completedTypes().isEmpty());a.stage=Stage.READY_TO_REPORT;assertFalse(s.report(liege()));assertTrue(s.report(a.liege));assertFalse(s.report(a.liege));assertEquals(1,s.completedTypes().size());assertEquals(Stage.REPORTED,s.history().get(0).stage);}
    @Test public void creditsAndReportsSurvivePlayerReloadWithoutPromoting(){KOMEPlayerProgression p=new KOMEPlayerProgression();p.setCanonicalRank(KOMEProgressionRank.KNIGHT);for(Type type:Type.values()){KOMEKnightCommission a=commission(type);p.getKnightService().offer(a);a.stage=Stage.READY_TO_REPORT;assertTrue(p.getKnightService().report(a.liege));}p.readFromNBT(p.writeToNBT());assertEquals(5,p.getKnightService().completedTypes().size());assertEquals(5,p.getKnightService().history().size());assertEquals(KOMEProgressionRank.KNIGHT,p.getCanonicalRank());assertFalse(p.isCompleted(KOMEProgressionAchievement.forID("knight.earn_new_standing")));}
    @Test public void unusedEligibleTypesNeverRepeat(){KOMEKnightServiceRecord s=new KOMEKnightServiceRecord();for(Type type:Type.values()){assertTrue(s.eligible(Arrays.asList(Type.values())).contains(type));KOMEKnightCommission a=commission(type);s.offer(a);a.stage=Stage.READY_TO_REPORT;s.report(a.liege);assertFalse(s.eligible(Arrays.asList(Type.values())).contains(type));}assertTrue(s.eligible(Arrays.asList(Type.values())).isEmpty());}
    @Test public void unavailableTemplatesStayExcluded(){KOMEKnightServiceRecord s=new KOMEKnightServiceRecord();assertEquals(Collections.singletonList(Type.RELIEF),s.eligible(Collections.singletonList(Type.RELIEF)));}
    @Test public void failedChargeDoesNotEraseEarnedHistory(){KOMEKnightServiceRecord s=new KOMEKnightServiceRecord();KOMEKnightCommission first=commission(Type.RELIEF);s.offer(first);first.stage=Stage.READY_TO_REPORT;s.report(first.liege);KOMEKnightCommission failed=commission(Type.SETTLEMENT_DEFENSE);s.offer(failed);failed.stage=Stage.FAILED;s.clearFailed();assertNull(s.assignment());assertTrue(s.completedTypes().contains(Type.RELIEF));assertTrue(s.eligible(Arrays.asList(Type.values())).contains(Type.SETTLEMENT_DEFENSE));}
    @Test public void corruptAssignmentsLoadSafely(){KOMEKnightCommission a=commission(Type.RELIEF);NBTTagCompound n=a.writeToNBT();n.setString("Type","future_type");assertNull(KOMEKnightCommission.readFromNBT(n));n=a.writeToNBT();n.setString("Token","not-a-uuid");assertNull(KOMEKnightCommission.readFromNBT(n));n=a.writeToNBT();n.setDouble("X",Double.NaN);assertNull(KOMEKnightCommission.readFromNBT(n));}
    @Test public void resetClearsNewState(){KOMEPlayerProgression p=new KOMEPlayerProgression();p.getKnightService().offer(commission(Type.RELIEF));p.reset();assertNull(p.getKnightService().assignment());assertTrue(p.getKnightService().history().isEmpty());}
    @Test public void manyRetriesKeepSuccessfulReportProvenance(){KOMEKnightServiceRecord s=new KOMEKnightServiceRecord();KOMEKnightCommission success=commission(Type.RELIEF);s.offer(success);success.stage=Stage.READY_TO_REPORT;s.report(success.liege);for(int i=0;i<40;i++){KOMEKnightCommission failed=commission(Type.SETTLEMENT_DEFENSE);s.offer(failed);failed.stage=Stage.FAILED;s.clearFailed();}s.readFromNBT(s.writeToNBT());assertEquals(32,s.history().size());assertEquals(success.token,s.history().get(0).token);assertTrue(s.completedTypes().contains(Type.RELIEF));}
}
